local ffi = require("ffi")
print(pcall(function() ffi.cdef("int x(") end))
print(pcall(function() ffi.new("int", {}) end))
print(pcall(function() ffi.new("struct {int x;}", 1, 2) end))
print(pcall(function() local x = ffi.new("int[2]") x[0] = "a" end))
print(pcall(function() ffi.cast("int", nil) end))
print(pcall(function() return ffi.sizeof(1) end))
print(pcall(function() return ffi.string(1) end))
print(pcall(function() return ffi.C.strlen end))
print(pcall(function() local s = ffi.new("struct {int x;}") return s < s end))
print(pcall(function() return ffi.new("int") .. "" end))
print(pcall(function() local t = ffi.typeof("int") return t.foo end))
print(pcall(function() return 1LL < ffi.new("void*") end))
print(pcall(function() return ffi.errno("x") end))
print(pcall(function() return ffi.metatype("struct {int y;}", {})(1, 2) end))
print(pcall(function() ffi.C.foo = 1 end))
print(pcall(function() return ffi.new("struct {int x;}")() end))
print(pcall(function() for k in pairs(1LL) do end end))
